#include <iostream>
using namespace std;

class Counter {
public:
    int count;
    Counter() { count = 0; }
    void add(int k) { count += k; }
};

int main() {   //@ @layout open:uml_visualizer
    Counter c;   //@ @tts [next] 建立一個計數器
    c.add(2);   //@ @guide uml:c @tts [next] 加二
    c.add(3);   //@ @guide uml:c @tts [next] 再加三
    cout << c.count << endl;   //@ @guide uml:c @tts [next] 現在是五
    return 0;   //@ @tts [continue] 程式結束
}
